- Check projectSettings first (FR6 precedence)
- Return true if "dangerously-skip-permissions" === true (FR3)
- Return true if "defaultMode" === "bypassPermissions" (FR4)
- Return false otherwise
- Define ClaudeSettings interface: { "dangerously-skip-permissions"?: boolean; defaultMode?: string }
- Add TSDoc for factory and interface

Approximate code structure:
```typescript
export interface ClaudeSettings {
  'dangerously-skip-permissions'?: boolean;
  defaultMode?: string;
}

export interface CreateClaudeSettingsComputerReturn {
  isYoloEnabled(
    projectSettings: ClaudeSettings | null,
    globalSettings: ClaudeSettings | null
  ): boolean;
}

export function createClaudeSettingsComputer(): CreateClaudeSettingsComputerReturn {
  function isYoloEnabled(
    projectSettings: ClaudeSettings | null,
    globalSettings: ClaudeSettings | null
  ): boolean {
    // Check project settings first (takes precedence)
    const settings = projectSettings ?? globalSettings;
    if (!settings) return false;

    if (settings['dangerously-skip-permissions'] === true) return true;
    if (settings.defaultMode === 'bypassPermissions') return true;

    return false;
  }

  return { isYoloEnabled };
}
```

